<template><main class="admin-profile"><section class="card"><p>STOCKWELL ADMIN</p><h1>Administrator Profile</h1><div v-if="loading">Loading…</div><div v-else-if="error">{{ error }}</div><div v-else><h2>{{ user.full_name || 'Administrator' }}</h2><p>{{ user.email }}</p><span class="role">ADMINISTRATOR</span><dl><dt>Phone</dt><dd>{{ user.phone_number || 'Not provided' }}</dd><dt>Account created</dt><dd>{{ formatDate(user.created_at) }}</dd><dt>User ID</dt><dd>#{{ user.user_id || '—' }}</dd><dt>Access</dt><dd>Full administrator</dd></dl><div class="actions"><router-link to="/admin">Back to Dashboard</router-link><router-link to="/admin/management">Open Administration</router-link></div></div></section></main></template>
<script setup>import{onMounted,ref}from'vue';import api from'../services/api.js';const loading=ref(true),error=ref(''),user=ref({});const formatDate=v=>v?new Date(v).toLocaleDateString('en-ZA',{day:'2-digit',month:'short',year:'numeric'}):'—';onMounted(async()=>{try{const r=await api.get('/auth/me');user.value=r.data?.user||r.data||{}}catch(e){error.value=e.response?.data?.message||e.response?.data?.error||'Could not load administrator profile.'}finally{loading.value=false}});</script>
<style scoped>.admin-profile{min-height:100vh;padding:50px 20px;background:var(--bg);color:var(--text)}.card{max-width:850px;margin:auto;padding:32px;border:1px solid var(--border);border-radius:22px;background:var(--card);box-shadow:0 15px 40px rgba(0,0,0,.1)}h1{font-size:42px;margin:8px 0 25px}.card>p{letter-spacing:.15em;font-size:11px;color:var(--gold);font-weight:800}.role{display:inline-block;padding:7px 12px;border-radius:999px;background:var(--gold);color:#221a3a;font-size:10px;font-weight:800}dl{margin:28px 0}dt{font-size:10px;letter-spacing:.12em;opacity:.6;margin-top:15px}dd{margin:5px 0 0;font-weight:700}.actions{display:flex;gap:10px;flex-wrap:wrap}.actions a{padding:11px 16px;border:1px solid var(--border);border-radius:999px;color:var(--text);text-decoration:none}.actions a:last-child{background:var(--gold);color:#221a3a;border-color:var(--gold)}</style>
